function bareLlmModel(p){
  if(!p) return "";
  if(p.default_model_bare) return p.default_model_bare;
  var m=p.model||"";
  var i=m.indexOf("/");
  return i>=0?m.slice(i+1):m;
}
function llmRefinerProviderList(){
  return (S.llmProviders||[]).filter(function(p){return p.name!=="demo";});
}
var HOSTED_LLM_PROVIDERS={gemini:1,claude:1,openai:1,openrouter:1};
function isHostedLlmProvider(name){
  return !!HOSTED_LLM_PROVIDERS[(name||"").toLowerCase()];
}
function validateLlmApiBase(value,providerName){
  var v=(value||"").trim();
  if(!v) return null;
  if(/^https?:\/\/.+/i.test(v)) return null;
  var prov=(providerName||"provider").trim()||"provider";
  var msg=prov+" has an invalid api_base configuration. api_base must be a full http:// or https:// URL.";
  if(isHostedLlmProvider(prov)){
    msg+=" For hosted providers, leave api_base empty unless you are using a custom gateway.";
  }
  if(/^[A-Za-z0-9._-]{20,}$/.test(v)&&v.indexOf("://")<0&&v.indexOf("/")<0){
    msg+=" The current value looks like an API key, not a URL; put it in the provider API key field or the matching *_API_KEY environment variable instead.";
  }
  return msg;
}
function llmProviderDefaults(name){
  var p=(S.llmProviders||[]).find(function(x){return x.name===name});
  if(!p) return {model:"",endpoint:"",hint:"",api_key_env:""};
  var bare=bareLlmModel(p);
  var models=(p.known_models&&p.known_models.length)?p.known_models.slice():[];
  if(bare&&models.indexOf(bare)<0) models.unshift(bare);
  return {
    model: models[0]||bare||"",
    endpoint: p.api_base||"",
    hint: models.length?models.join(", "):"",
    api_key_env: p.api_key_env||""
  };
}
function ensureLlmRefinerDefaults(){
  var list=llmRefinerProviderList();
  if(!list.length) return;
  var names=list.map(function(p){return p.name;});
  var legacy={"anthropic":"claude","azure":"openai","custom":null};
  if(cfg.llm_provider&&legacy[cfg.llm_provider]){
    var mapped=legacy[cfg.llm_provider];
    if(mapped&&names.indexOf(mapped)>=0) cfg.llm_provider=mapped;
  }
  if(!cfg.llm_provider||names.indexOf(cfg.llm_provider)<0){
    cfg.llm_provider=names.indexOf("gemini")>=0?"gemini":names[0];
  }
  if(cfg.llm_endpoint_url&&validateLlmApiBase(cfg.llm_endpoint_url,cfg.llm_provider)){
    cfg.llm_endpoint_url=null;
  }
  var staleModels={"gpt-4-turbo":1,"gpt-4":1,"gemini-2.0-flash":1};
  if(!cfg.llm_model||staleModels[cfg.llm_model]){
    var d=llmProviderDefaults(cfg.llm_provider);
    if(d.model) cfg.llm_model=d.model;
    if(!cfg.llm_endpoint_url&&d.endpoint) cfg.llm_endpoint_url=d.endpoint;
  }
}
function onLlmRefinerProviderChange(){
  var pr=document.getElementById("s_llm_provider");
  if(!pr) return;
  syncLlmSettingsDraftFromInputs();
  var d=llmProviderDefaults(pr.value);
  cfg.llm_provider=pr.value;
  cfg.llm_model=d.model;
  cfg.llm_endpoint_url=d.endpoint||null;
  render();
}
function syncLlmSettingsDraftFromInputs(){
  var en=document.getElementById("s_llm_enabled");
  var pr=document.getElementById("s_llm_provider");
  var mo=document.getElementById("s_llm_model");
  var key=document.getElementById("s_llm_key");
  var ep=document.getElementById("s_llm_endpoint");
  var apr=document.getElementById("s_agent_llm_provider");
  var amo=document.getElementById("s_agent_llm_model");
  if(en) cfg.llm_enabled=en.checked;
  if(pr) cfg.llm_provider=pr.value;
  if(mo) cfg.llm_model=mo.value;
  if(key) cfg.llm_api_key=key.value;
  if(ep) cfg.llm_endpoint_url=ep.value||null;
  if(apr) cfg.agentic_planner_provider=apr.value;
  if(amo) cfg.agentic_planner_model=amo.value;
  if(!cfg.agentic_planner_provider) cfg.agentic_planner_provider=cfg.llm_provider||"";
  if(!cfg.agentic_planner_model) cfg.agentic_planner_model=cfg.llm_model||"";
}
async function testLlmRefinerSettings(){
  var pr=document.getElementById("s_llm_provider");
  var mo=document.getElementById("s_llm_model");
  var key=document.getElementById("s_llm_key");
  var ep=document.getElementById("s_llm_endpoint");
  var promptEl=document.getElementById("s_llm_test_prompt");
  var provider=(pr&&pr.value)||cfg.llm_provider||"gemini";
  if(promptEl) S.llmRefinerTestPrompt=promptEl.value;
  syncLlmSettingsDraftFromInputs();
  var endpointErr=validateLlmApiBase(cfg.llm_endpoint_url,cfg.llm_provider);
  if(endpointErr){ alert(endpointErr); return; }
  S.llmRefinerTest={busy:true};
  render();
  var body={
    model:(mo&&mo.value)||cfg.llm_model||"",
    api_key:(key&&key.value)||cfg.llm_api_key||"",
    prompt:(S.llmRefinerTestPrompt||"").trim()||"Say hello in one short sentence.",
    timeout:30
  };
  if(!isHostedLlmProvider(provider)&&((ep&&ep.value)||cfg.llm_endpoint_url)){
    body.endpoint_url=(ep&&ep.value)||cfg.llm_endpoint_url||"";
  }
  try{
    var r=await POST("/api/llm-providers/"+encodeURIComponent(provider)+"/test",body);
    S.llmRefinerTest=Object.assign({busy:false},r);
    loadLlmCalls(true);
  }catch(e){
    S.llmRefinerTest={busy:false,ok:false,error:apiErr(e)};
    render();
  }
}
function toggleLlmRefinerTestLog(){
  if(!S.llmRefinerTest) return;
  S.llmRefinerTest.showLog=!S.llmRefinerTest.showLog;
  render();
}
async function loadLlmCalls(force){
  if(S.llmCallsLoading) return;
  if(S.llmCallsFetched&&!force) return;
  S.llmCallsLoading=true;
  try{
    var d=await GET("/api/llm/calls?limit=50");
    S.llmCalls=d.calls||[];
    S.llmCallsFetched=true;
    render();
  }catch(e){addLog("LLM calls load failed: "+e.message,"err")}
  finally{S.llmCallsLoading=false}
}
