async function loadDebugSessions(){
  if(S.debugSessionsLoading) return;
  S.debugSessionsLoading=true;
  try{
    S.debugSessions=await GET("/api/sessions");
    render();
  }catch(e){addLog("Debug load failed: "+e.message,"err")}
  finally{S.debugSessionsLoading=false}
}

async function loadDebugSession(sid){
  try{
    S.debugSelSid=sid;
    S.debugSession=await GET("/api/sessions/"+sid+"/debug");
    S._dbgRunCfg={};
    render();
  }catch(e){addLog("Debug session load failed: "+e.message,"err")}
}

function dbgConfigValue(key,val){
  if(val==null) return "—";
  if(key==="regex_set"||key==="quality_rule_set"){
    if(key==="regex_set"){
      var n=val&&val.patterns?Object.keys(val.patterns).length:0;
      return "RegexSet · "+n+" pattern(s) · replace_all="+!!(val&&val.replace_all);
    }
    var qr=val&&val.rules?val.rules.length:0;
    return "QualityRuleSet · "+qr+" rule(s)";
  }
  var s=typeof val==="object"?JSON.stringify(val):String(val);
  if(s.length>240) s=s.substring(0,240)+"…";
  return s;
}

function dbgRawJson(sel){
  try{
    var raw=JSON.stringify(sel,null,2);
    if(raw.length>150000) return raw.substring(0,150000)+"\n\n… truncated ("+raw.length+" chars) …";
    return raw;
  }catch(e){return String(e.message||e)}
}

async function flushSession(sid){
  if(!sid||S.debugFlushBusy) return;
  S.debugFlushBusy=true;
  render();
  try{
    var r=await POST("/api/sessions/"+sid+"/flush");
    addLog("Flushed session "+sid+" → "+r.path,"ok");
    if(S.debugSelSid===sid) await loadDebugSession(sid);
    else await loadDebugSessions();
  }catch(e){addLog("Flush failed: "+e.message,"err")}
  finally{
    S.debugFlushBusy=false;
    try{render()}catch(_){}
  }
}

async function flushAllSessions(){
  if(S.debugFlushBusy) return;
  S.debugFlushBusy=true;
  render();
  try{
    var r=await POST("/api/sessions/flush_all");
    addLog("Flushed "+r.count+" sessions","ok");
    await loadDebugSessions();
    if(S.debugSelSid) await loadDebugSession(S.debugSelSid);
  }catch(e){addLog("Flush all failed: "+e.message,"err")}
  finally{
    S.debugFlushBusy=false;
    try{render()}catch(_){}
  }
}

