function toggleRunConfig(runId){
  var el=document.getElementById("rc_"+runId);
  if(!el) return;
  var open=el.style.display==="none";
  el.style.display=open?"block":"none";
  if(open&&!el.textContent){
    var snap=(S._dbgRunCfg&&S._dbgRunCfg[runId])||{};
    try{
      var raw=JSON.stringify(snap,null,2);
      if(raw.length>80000) raw=raw.substring(0,80000)+"\n… truncated …";
      el.textContent=raw;
    }catch(e){el.textContent=String(e.message||e)}
  }
}

