function scanModeLabel(){
  if(cfg.scan_mode==="pii") return "PII only";
  if(cfg.scan_mode==="quality") return "Quality only";
  return "PII + Quality";
}


async function executeQualityProfiler(){
  if(!S.sid){
    S.logs=[];S.result=null;S.prog=5;S.pmsg="Creating session...";S.view="scanning";render();
    addLog("Starting Quality Profiler for "+S.fname,"step");
    var fd=new FormData();fd.append("file",S.file);
    fd.append("table","data."+S.fname.replace(/\.[^.]+$/,"").replace(/[^a-zA-Z0-9_]/g,"_"));
    fd.append("equation","independent");
    var sess=await POST("/api/sessions",fd);
    S.sid=sess.session_id;addLog("Session: "+sess.session_id,"ok");
    if(S.es)S.es.close();
    var es=new EventSource("/api/sessions/"+sess.session_id+"/stream");
    es.onmessage=function(e){if(e.data==="[DONE]"){es.close();return}try{var d=JSON.parse(e.data);if(d.message)addLog(d.message,d.message.indexOf("ERROR")>=0?"err":"")}catch(x){}};
    es.onerror=function(){es.close()};S.es=es;
  } else {
    S.view="scanning";render();
  }

  try{
    S.prog=15;S.pmsg="Profiling...";render();addLog("Running profiler...","step");
    var pf=new FormData();
    var selectedCols = S.columns.filter(c => c.on).map(c => c.name);
    if(selectedCols.length > 0) pf.append("selected_columns", JSON.stringify(selectedCols));
    await fetch("/api/sessions/"+S.sid+"/step/profile", {method:"POST", body: pf});
    await wait(S.sid,["profiled","profiling_complete","error"]);
    addLog("Profiling done","ok");
    set({view:"quality-review"});
  }catch(e){addLog("ERROR: "+e.message,"err");S.pmsg="Failed";render()}
}

async function executeQualityScanBypass(){
  // Used when bypassing the profiler with loaded rules
  if(!S.sid){
    S.logs=[];S.result=null;S.prog=5;S.pmsg="Creating session...";S.view="scanning";render();
    addLog("Starting Quality Scan for "+S.fname,"step");
    var fd=new FormData();fd.append("file",S.file);
    fd.append("table","data."+S.fname.replace(/\.[^.]+$/,"").replace(/[^a-zA-Z0-9_]/g,"_"));
    fd.append("equation","independent");
    var sess=await POST("/api/sessions",fd);
    S.sid=sess.session_id;addLog("Session: "+sess.session_id,"ok");
    if(S.es)S.es.close();
    var es=new EventSource("/api/sessions/"+sess.session_id+"/stream");
    es.onmessage=function(e){if(e.data==="[DONE]"){es.close();return}try{var d=JSON.parse(e.data);if(d.message)addLog(d.message,d.message.indexOf("ERROR")>=0?"err":"")}catch(x){}};
    es.onerror=function(){es.close()};S.es=es;
  }
  
  var tpl = document.getElementById("qualityTemplateSelect");
  if(tpl && tpl.value) {
    var tr = await fetch("/api/sessions/"+S.sid+"/draft/quality/template", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({template_name: tpl.value})
    });
    if(!tr.ok){alert("Failed to load template");return}
    var tj=await tr.json();
    if(tj.ge_code) S.pasteCode=tj.ge_code;
    cfg.quality_config_name=tpl.value;
  }

  executeQualityScan();
}

async function executeQualityScanUpload(inp){
  if(!inp.files[0])return;
  
  if(!S.sid){
    S.logs=[];S.result=null;S.prog=5;S.pmsg="Creating session...";S.view="scanning";render();
    addLog("Starting Quality Scan for "+S.fname,"step");
    var fd=new FormData();fd.append("file",S.file);
    fd.append("table","data."+S.fname.replace(/\.[^.]+$/,"").replace(/[^a-zA-Z0-9_]/g,"_"));
    fd.append("equation","independent");
    var sess=await POST("/api/sessions",fd);
    S.sid=sess.session_id;addLog("Session: "+sess.session_id,"ok");
    if(S.es)S.es.close();
    var es=new EventSource("/api/sessions/"+sess.session_id+"/stream");
    es.onmessage=function(e){if(e.data==="[DONE]"){es.close();return}try{var d=JSON.parse(e.data);if(d.message)addLog(d.message,d.message.indexOf("ERROR")>=0?"err":"")}catch(x){}};
    es.onerror=function(){es.close()};S.es=es;
  }
  
  var fdUpload=new FormData();fdUpload.append("file",inp.files[0]);
  try{
    await fetch("/api/sessions/"+S.sid+"/draft/quality/upload",{method:"POST",body:fdUpload});
    inp.value="";
    executeQualityScan();
  }catch(e){alert("Upload failed");}
}

async function executePiiScan(){
  if(!S.sid){
    S.logs=[];S.result=null;S.prog=5;S.pmsg="Creating session...";S.view="scanning";render();
    addLog("Starting PII scan for "+S.fname,"step");
    var fd=new FormData();fd.append("file",S.file);
    fd.append("table","data."+S.fname.replace(/\.[^.]+$/,"").replace(/[^a-zA-Z0-9_]/g,"_"));
    fd.append("equation","independent");
    var sess=await POST("/api/sessions",fd);
    S.sid=sess.session_id;addLog("Session: "+sess.session_id,"ok");
    if(S.es)S.es.close();
    var es=new EventSource("/api/sessions/"+sess.session_id+"/stream");
    es.onmessage=function(e){if(e.data==="[DONE]"){es.close();return}try{var d=JSON.parse(e.data);if(d.message)addLog(d.message,d.message.indexOf("ERROR")>=0?"err":"")}catch(x){}};
    es.onerror=function(){es.close()};S.es=es;
  } else {
    S.view="scanning";render();
  }
  
  try{
    S.prog=70;S.pmsg="PII detection...";render();addLog("Running PII...","step");
    var pf=new FormData();
    var selectedCols = S.columns.filter(c => c.on).map(c => c.name);
    if(selectedCols.length > 0) pf.append("pii_columns", JSON.stringify(selectedCols));
    
    await fetch("/api/sessions/"+S.sid+"/step/pii",{method:"POST",body:pf});
    await wait(S.sid,["pii_complete","error"]);
    addLog("PII done","ok");
    
    S.prog=95;S.pmsg="Fetching results...";render();
    var fin=await GET("/api/sessions/"+S.sid);
    S.result=fin;S.scanDone=true;
    syncScanLinksFromResult(fin);
    saveLastSession(S.sid,S.table||fin.table_name);
    S.prog=100;S.pmsg="Done";addLog("Scan complete!","ok");
    render();
  }catch(e){addLog("ERROR: "+e.message,"err");S.pmsg="Failed";render()}
}

async function executeQualityScan(){
  S.view="scanning";
  try{
    S.prog=45;S.pmsg="Quality checks...";render();addLog("Running quality...","step");
    await POST("/api/sessions/"+S.sid+"/step/quality");
    await wait(S.sid,["quality_complete","error"]);
    addLog("Quality done","ok");
    
    S.prog=95;S.pmsg="Fetching results...";render();
    var fin=await GET("/api/sessions/"+S.sid);
    S.result=fin;S.scanDone=true;
    syncScanLinksFromResult(fin);
    saveLastSession(S.sid,S.table||fin.table_name);
    S.prog=100;S.pmsg="Done";addLog("Scan complete!","ok");
    if(fin.approved) S.approved=fin.approved;
    await loadApproved();
    set({view:"quality"});
  }catch(e){addLog("ERROR: "+e.message,"err");S.pmsg="Failed";render()}
}

