async function wait(sid,ts){
  var limit=parseInt(cfg.scan_wait_timeout_sec,10);
  if(isNaN(limit)||limit<60) limit=360;
  var misses=0;
  for(var i=0;i<limit;i++){
    await new Promise(function(r){setTimeout(r,1000)});
    try{
      var st=await GET("/api/sessions/"+sid);
      misses=0;
      if(ts.indexOf(st.status)>=0) return st;
    }catch(e){
      misses++;
      if(misses>=3) throw new Error("Session not found — scan may have been lost. Try again or refresh. ("+e.message+")");
    }
  }
  throw new Error("Timed out waiting for scan after "+limit+"s (expected: "+ts.join(", ")+")");
}
async function cancelScan(){
  if(S.sid)try{await fetch("/api/sessions/"+S.sid,{method:"DELETE"})}catch(e){}
  if(S.es)S.es.close();addLog("Cancelled","err");S.pmsg="Cancelled";render();
}
