async function loadApproved(){
  if(!S.sid) return;
  var d=await GET("/api/sessions/"+S.sid+"/approved");
  S.approved=d||{items:[],summary:{}};
}
function normQualityColumn(col){
  if(!col||col==="Table-Level"||col==="__table__") return "__table__";
  return col;
}
function qualityRuleSig(ruleOrPayload){
  if(!ruleOrPayload) return "";
  if(typeof ruleOrPayload==="string") return ruleOrPayload.toLowerCase();
  var impl=ruleOrPayload.implementation||{};
  return (ruleOrPayload.expectation_type||ruleOrPayload.rule||ruleOrPayload.type
    ||impl.expectation_type||ruleOrPayload.name||"").toLowerCase();
}
var QUALITY_GE_TO_ODCS={
  "expect_column_values_to_not_be_null":"missingcount",
  "expect_column_values_to_be_null":"missingcount",
  "expect_column_values_to_be_unique":"duplicatecount",
  "expect_column_values_to_be_in_set":"validvalues",
  "expect_column_values_to_match_regex":"regex",
  "expect_column_values_to_be_between":"range",
  "expect_column_values_to_be_of_type":"datatype",
  "expect_table_row_count_to_be_between":"rowcount",
  "expect_table_row_count_to_equal":"rowcount"
};
function qualityRuleSigVariants(ruleSig){
  var sig=qualityRuleSig(typeof ruleSig==="object"?ruleSig:ruleSig);
  var out={};
  if(sig) out[sig]=1;
  var mapped=QUALITY_GE_TO_ODCS[sig];
  if(mapped) out[mapped]=1;
  return out;
}
function isQualityRuleApproved(column,ruleSig){
  var c=normQualityColumn(column);
  var want=qualityRuleSigVariants(ruleSig);
  return (S.approved.items||[]).some(function(p){
    if(p.kind!=="quality") return false;
    if(normQualityColumn(p.column)!==c) return false;
    if(p.label&&want[p.label.toLowerCase()]) return true;
    var got=qualityRuleSigVariants(p.payload);
    for(var k in want){if(got[k]) return true}
    return false;
  });
}
function isApproved(column,kind,ruleSig){
  if(kind==="quality") return isQualityRuleApproved(column,ruleSig);
  return (S.approved.items||[]).some(function(p){
    return p.kind===kind&&p.column===column;
  });
}
function latestRunId(runType){
  var runs=(S.result&&S.result.runs)||[];
  for(var i=runs.length-1;i>=0;i--){
    if(!runType||runs[i].run_type===runType) return runs[i].run_id;
  }
  return "";
}
function latestQualityResults(){
  var runs=(S.result&&S.result.runs)||[];
  for(var i=runs.length-1;i>=0;i--){
    var rt=runs[i].run_type;
    if((rt==="scan_quality"||rt==="unified")&&runs[i].quality_results&&runs[i].quality_results.length){
      return runs[i].quality_results;
    }
  }
  return [];
}
async function approvePii(column,detection,runId,source){
  try{
    if(!S.sid) await ensureSession();
    var src=source||(S.view.indexOf("discover")>=0?"discovery":(detection&&detection.decision_path==="manual"?"manual":"scan"));
    await POST("/api/sessions/"+S.sid+"/approved/pii",
      {column:column,detection:detection,source_run_id:runId||null,source:src});
    await loadApproved();toast("PII added to basket: "+column);render();
  }catch(e){alert("Approve failed: "+e.message)}
}
// ── PII page — all columns, manual flag / unflag, approve all flagged ────────
function piiScanDetection(col){
  return (S.result&&S.result.pii_detections||[]).find(function(x){return x.column===col})||null;
}
function isPiiRejected(col){return !!(S.piiRejected&&S.piiRejected[col])}
function isPiiManual(col){return !!(S.piiManual&&S.piiManual[col])}
function isPiiFlaggedCol(col){
  if(isPiiRejected(col)) return false;
  if(isPiiManual(col)) return true;
  var d=piiScanDetection(col);
  return !!(d&&d.detected);
}
function piiFlagSourceMeta(col){
  if(isPiiRejected(col)) return {key:"unflagged",label:"unflagged",chip:"chip-muted"};
  if(isPiiManual(col)) return {key:"manual",label:"manual flag",chip:"pii-src-manual"};
  var d=piiScanDetection(col);
  if(d&&d.detected) return {key:"auto",label:"auto detected",chip:"pii-src-auto"};
  if(d&&(d.presidio_score||d.gliner_score)) return {key:"signal",label:"signal only",chip:"pii-src-signal"};
  return {key:"none",label:"—",chip:"chip-muted"};
}
function buildApprovePiiDetection(col){
  if(isPiiRejected(col)) return null;
  if(isPiiManual(col)){
    var m=S.piiManual[col];
    return {column:col,detected:true,entity_type:m.entity_type||"PII",confidence:m.confidence!=null?m.confidence:1,decision_path:"manual"};
  }
  var d=piiScanDetection(col);
  if(d&&d.detected) return d;
  return null;
}
function allPiiColumnNames(){
  var seen={},out=[];
  function add(n){if(n&&seen[n]===undefined){seen[n]=1;out.push(n)}}
  (S.columns||[]).forEach(function(c){add(c.name||c.column||c)});
  (S.result&&S.result.pii_detections||[]).forEach(function(d){add(d.column)});
  return out.sort();
}
async function ensurePiiColumns(){
  if(S.columns&&S.columns.length) return;
  if(!S.sid) return;
  try{
    var d=await GET("/api/sessions/"+S.sid+"/data/columns");
    S.columns=(d.columns||[]).map(function(c){
      var n=c.column||c.name||c;
      return {name:n,on:c.include_in_scan!==false};
    });
  }catch(_){
    try{
      var smp=await GET("/api/sessions/"+S.sid+"/sample?rows=1");
      if(smp.columns) S.columns=smp.columns.map(function(n){return {name:n,on:true}});
    }catch(__){}
  }
}
async function openPiiPage(){
  try{await ensureSession()}catch(e){alert(e.message);return}
  await ensurePiiColumns();
  await loadApproved();
  set({view:"pii"});
}
function guessPiiEntity(col){
  var c=col.toLowerCase();
  if(/email|mail/.test(c)) return "EMAIL_ADDRESS";
  if(/phone|mobile|msisdn|tel/.test(c)) return "PHONE_NUMBER";
  if(/iban|account|card|wallet/.test(c)) return "CREDIT_CARD";
  if(/name|person/.test(c)) return "PERSON";
  if(/address|street|city/.test(c)) return "LOCATION";
  if(/id|ssn|national/.test(c)) return "ID";
  return "PII";
}
function flagPiiColumn(col){
  var cur=isPiiManual(col)?(S.piiManual[col].entity_type||""):"";
  var et=prompt("PII entity type for \""+col+"\":",cur||guessPiiEntity(col));
  if(!et)return;
  S.piiManual=S.piiManual||{};S.piiRejected=S.piiRejected||{};
  delete S.piiRejected[col];
  S.piiManual[col]={entity_type:et,detected:true,confidence:1,decision_path:"manual"};
  render();
}
async function unflagPiiColumn(col){
  S.piiManual=S.piiManual||{};S.piiRejected=S.piiRejected||{};
  delete S.piiManual[col];
  S.piiRejected[col]=true;
  var item=(S.approved.items||[]).find(function(p){return p.kind==="pii"&&p.column===col});
  if(item){try{await deleteApproved(item.prop_id)}catch(e){}}
  render();
}
async function approveAllPiiFlagged(){
  try{if(!S.sid) await ensureSession()}catch(e){alert(e.message);return}
  var cols=allPiiColumnNames().filter(isPiiFlaggedCol);
  if(!cols.length){alert("No flagged PII columns. Use + flag PII or wait for scan detections.");return}
  var runId=latestRunId("scan_pii"),n=0;
  for(var i=0;i<cols.length;i++){
    if(isApproved(cols[i],"pii")) continue;
    var det=buildApprovePiiDetection(cols[i]);
    if(!det) continue;
    try{
      await POST("/api/sessions/"+S.sid+"/approved/pii",
        {column:cols[i],detection:det,source_run_id:runId||null,
         source:isPiiManual(cols[i])?"manual":"scan"});
      n++;
    }catch(e){alert("Approve failed for "+cols[i]+": "+e.message);break}
  }
  await loadApproved();
  toast("Added "+n+" PII column(s) to basket — merge from Approved to update contract");
  render();
}
