    await ensureSession();
    await POST("/api/sessions/"+S.sid+"/approved/quality",
      {column:normalizeQualityApproveColumn(column),rule:rule,source_run_id:runId||null,
       source:(S.view.indexOf("discover")>=0?"discovery":"scan")});
