function qualityEvalSummaryBar(summary,opts){
  if(!summary||!summary.total) return "";
  opts=opts||{};
  var passed=summary.passed||0, failed=summary.failed||0, total=summary.total||0;
  var pct=total?Math.round((passed/total)*100):0;
  var filt=S.qResultFilter||"all";
  var failOnly=failed>0?" has-fail":"";
  return "<div class='qeval-summary"+failOnly+"'>"+
    "<div class='qeval-stat pass'><span class='qstatus-icon' style='background:var(--green);color:#fff;width:20px;height:20px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem'>✓</span>"+
      "<span><span class='num'>"+passed+"</span> pass</span></div>"+
    "<div class='qeval-stat fail'><span class='qstatus-icon' style='background:var(--red-text);color:#fff;width:20px;height:20px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:.75rem'>✗</span>"+
      "<span><span class='num'>"+failed+"</span> fail</span></div>"+
    "<div class='qeval-bar' title='"+passed+" of "+total+" passed'><div class='qeval-bar-fill' style='width:"+pct+"%'></div></div>"+
    "<span style='font-size:.72rem;color:var(--muted);font-family:IBM Plex Mono,monospace'>"+total+" rules</span>"+
    (opts.showFilters!==false?
      "<div class='qeval-filters'>"+
        "<button type='button' class='qeval-filter"+(filt==="all"?" on":"")+"' onclick=\"setQResultFilter('all')\">all</button>"+
        "<button type='button' class='qeval-filter"+(filt==="pass"?" on":"")+"' onclick=\"setQResultFilter('pass')\">✓ passed</button>"+
        "<button type='button' class='qeval-filter fail-filter"+(filt==="fail"?" on":"")+"' onclick=\"setQResultFilter('fail')\">✗ failed</button>"+
      "</div>":"")+
  "</div>";
}
function matchEvalResult(rr,ev,i){
  if(!ev||!ev.length) return null;
  if(ev[i]){
    var a=(ev[i].expectation_type||ev[i].rule||"").toLowerCase();
    var b=(rr.expectation_type||rr.rule||"").toLowerCase();
    var ca=(ev[i].column||"").toLowerCase();
    var cb=(rr.column||"").toLowerCase();
    if(a===b&&ca===cb) return ev[i];
  }
  for(var j=0;j<ev.length;j++){
    var e=ev[j];
    if((e.expectation_type||e.rule||"").toLowerCase()===(rr.expectation_type||rr.rule||"").toLowerCase()&&
       (e.column||"").toLowerCase()===(rr.column||"").toLowerCase()) return e;
  }
  return ev[i]||null;
}
function sortQualityRows(rows){
  return rows.slice().sort(function(a,b){
    var af=a._eval&&(a._eval.success===false)?0:1;
    var bf=b._eval&&(b._eval.success===false)?0:1;
    if(af!==bf) return af-bf;
    return 0;
  });
}
function filterQualityRow(d,filt){
  if(!filt||filt==="all") return true;
  if(filt==="pass") return d.success===true;
  if(filt==="fail") return d.success===false;
  return true;
}
function qualityResultLabel(d){
  var rule=d.rule||d.expectation_type||"?";
  var col=d.column&&d.column!=="Table-Level"?" · "+d.column:"";
  return rule+col;
}
function qualityResultDetail(d){
  if(d.success) return "";
  return d.reason||(
    d.unexpected_count
      ? d.unexpected_count+" unexpected"
      : (d.observed_value!=null?String(d.observed_value):"failed")
  );
}
function qualityResultsTable(rows,runId){
  if(!rows.length) return "";
  var filt=S.qResultFilter||"all";
  var passed=rows.filter(function(d){return d.success}).length;
  var failed=rows.length-passed;
  var sorted=rows.slice().sort(function(a,b){
    var af=a.success===false?0:1, bf=b.success===false?0:1;
    return af-bf;
  });
  var visible=sorted.filter(function(d){return filterQualityRow(d,filt)});
  if(!visible.length&&filt!=="all") visible=sorted;
  return qualityEvalSummaryBar({total:rows.length,passed:passed,failed:failed})+
    qualityBatchBar(rows,runId)+
    "<div class='stitle' style='margin-top:16px'>expectations · "+(filt==="all"?"all":filt)+" ("+visible.length+")</div>"+
    "<div class='card' style='padding:0;overflow:hidden'><table class='tbl qeval-tbl'><thead><tr>"+
    "<th style='width:110px'>Status</th><th>Rule</th><th>Detail</th><th></th></tr></thead><tbody>"+
    visible.map(function(d){
      return "<tr class='"+qualityRowClass(d)+"'>"+
        "<td>"+qualityStatusCell(d)+"</td>"+
        "<td class='mono cell-strong'>"+E(qualityResultLabel(d))+"</td>"+
        "<td>"+qualityWhyCell(d)+"</td>"+
        "<td>"+apprBtn(d.column||"","quality",runId,d.rule||d.expectation_type)+"</td></tr>";
    }).join("")+"</tbody></table></div>";
}
// Render the parsed-rule table. evalMode adds an "evaluate against sample" button
// and a per-rule pass/fail column (Discovery uses it; Quality can too).
function pasteRulesTable(){
  if(!S.pasteRules.length)return "";
  var ev=(S.pasteEval&&S.pasteEval.results)||[];
  var indexed=S.pasteRules.map(function(rr,i){
    return {rr:rr,i:i,_eval:matchEvalResult(rr,ev,i)};
  });
  var sorted=sortQualityRows(indexed);
  var filt=S.qResultFilter||"all";
  var visible=sorted.filter(function(x){
    if(!x._eval) return filt==="all";
    return filterQualityRow(x._eval,filt);
  });
  if(!visible.length&&filt!=="all") visible=sorted;
  var rows=visible.map(function(x){
    var rr=x.rr,i=x.i,e=x._eval;
    var kw=rr.kwargs&&Object.keys(rr.kwargs).length?JSON.stringify(rr.kwargs):"";
    var apr=isQualityRuleApproved(rr.column,rr.expectation_type);
    return "<tr class='"+qualityRowClass(e)+"'>"+
      "<td>"+qualityStatusCell(e)+"</td>"+
      "<td class='mono cell-strong'>"+E(rr.expectation_type)+"</td>"+
      "<td class='mono'>"+E(rr.column||"table-level")+"</td>"+
      "<td class='mono' style='font-size:.72rem;color:var(--muted);max-width:180px;overflow:hidden;text-overflow:ellipsis' title='"+E(kw)+"'>"+E(kw||"—")+"</td>"+
      "<td>"+qualityWhyCell(e)+"</td>"+
      "<td><button class='btn btn-ghost btn-sm' onclick='approveParsedRule("+i+")'>"+(apr?"✓ approved":"+ approve")+"</button></td>"+
      "<td style='width:36px'><button class='btn btn-ghost btn-sm' style='color:var(--red)' onclick='S.pasteRules.splice("+i+",1);render()'>✕</button></td></tr>";
  }).join("");
  var sum=S.pasteEval&&S.pasteEval.summary;
  return (sum?qualityEvalSummaryBar(sum):"")+
    "<div class='card' style='padding:0;overflow:hidden;margin-top:12px'><table class='tbl qeval-tbl' style='font-size:.78rem'>"+
    "<thead><tr><th style='width:110px'>Status</th><th>Expectation</th><th>Column</th><th>Params</th><th>Detail</th><th></th><th></th></tr></thead><tbody>"+
    rows+"</tbody></table></div>"+
    (!sum&&S.pasteRules.length?"<div style='font-size:.74rem;color:var(--muted);margin-top:6px'>"+S.pasteRules.length+" rule(s) parsed — click ▶ evaluate to run on sample</div>":"");
}
function pasteErrorsBox(){
  if(!S.pasteErrors||!S.pasteErrors.length)return "";
  return "<div class='cbox' style='border-color:var(--amber);color:var(--amber);margin-top:10px;font-size:.74rem'>"+
    "<strong>"+S.pasteErrors.length+" line(s) skipped (not valid GE rules):</strong><ul style='margin:6px 0 0 16px'>"+
    S.pasteErrors.map(function(e){return "<li>line "+(e.line||"?")+": "+E(e.message)+(e.snippet?" — <span class='mono'>"+E(e.snippet)+"</span>":"")+"</li>"}).join("")+
    "</ul></div>";
}
// Shared paste panel. mode "quality" (parse + approve) or "discovery" (+ evaluate).
function vPasteRulesPanel(mode){
  var isDisc=mode==="discovery";
  var busy=S.pasteBusy;
  return "<div class='card card-pad' style='margin-bottom:20px'>"+
    "<div class='stitle' style='margin:0 0 4px'>paste Great Expectations rules</div>"+
    "<div style='color:var(--muted);font-size:.74rem;margin-bottom:8px'>"+
      (isDisc
        ? "Paste GE rule code for one column or a table-level rule, evaluate it against the sample, then approve. Only GE expectations run — pasted text is parsed, never executed."
        : "Paste the curated code from the interactive review, or load a generated program you edited in Jupyter, then parse, approve, and merge from the Approved page. Both a rules-only fragment and a full generated program are accepted — the text is parsed with AST/literals only and never executed.")+
    "</div>"+
    "<textarea id='pasteRulesBox' class='input mono' rows='7' style='width:100%;font-size:.78rem' placeholder=\"qa.add_gx_expectation(\n    expectation_name='expect_column_values_to_not_be_null',\n    column='phone',\n    mostly=0.95)\n\n# …or paste a full generated program's RULES = [...] block\">"+E(S.pasteCode||"")+"</textarea>"+
    "<div class='row' style='gap:10px;flex-wrap:wrap;align-items:center;margin-top:10px'>"+
      "<button class='btn btn-red' onclick=\"evaluatePastedRules('pasteRulesBox')\""+(busy?" disabled":"")+">"+(busy?"…":"▶ evaluate")+"</button>"+
      "<button class='btn btn-ghost' onclick=\"loadQualityPythonFile('pasteRulesBox')\">📄 load .py file</button>"+
      (isDisc?"<span style='color:var(--muted);font-size:.72rem'>rows</span><input id='pasteSubset' class='input mono' style='width:90px' placeholder='all'>":"")+
      (S.pasteRules.length?"<button class='btn btn-ghost' onclick='approveAllParsedRules()'>+ approve all ("+S.pasteRules.length+")</button>"+
        "<button class='btn btn-ghost' onclick='generateJupyterFromParsed()'>⧉ Generate Jupyter Code</button>"+
        "<button class='btn btn-ghost' onclick='savePastedRulesConfig()'>💾 save to registry</button>"+
        "<button class='btn btn-ghost' onclick='clearParsedRules()'>clear parsed</button>":"")+
    "</div>"+
    pasteErrorsBox()+
    pasteRulesTable()+
  "</div>";
}

// ── Settings ──
function applyUiPrefsFromGlobal(gs){
  if(!gs||typeof gs!=="object") return;
  var ui=gs.ui_prefs||gs;
  if(ui.scan_mode) cfg.scan_mode=ui.scan_mode;
  if(ui.pii_engines) cfg.pii_engines=ui.pii_engines;
  if(gs.automerge) cfg.automerge=gs.automerge;
  var pii=gs.pii||{};
  var ss=parseInt(pii.sample_size,10);
  if(!isNaN(ss)&&ss>=1) cfg.pii_sample_size=ss;
  var sw=parseInt(ui.scan_wait_timeout_sec,10);
  if(!isNaN(sw)&&sw>=60) cfg.scan_wait_timeout_sec=sw;
  var sse=parseFloat(ui.sse_ping_timeout_sec);
  if(!isNaN(sse)&&sse>=5) cfg.sse_ping_timeout_sec=sse;
  var llm=gs.llm_defaults&&typeof gs.llm_defaults==="object"?gs.llm_defaults:{};
  if(llm.provider!=null&&llm.provider!=="") cfg.llm_provider=llm.provider;
  if(llm.model!=null&&llm.model!=="") cfg.llm_model=llm.model;
  if(Object.prototype.hasOwnProperty.call(llm,"enabled")) cfg.llm_enabled=!!llm.enabled;
  if(Object.prototype.hasOwnProperty.call(llm,"endpoint_url")){
    cfg.llm_endpoint_url=llm.endpoint_url||null;
    if(cfg.llm_endpoint_url&&validateLlmApiBase(cfg.llm_endpoint_url,cfg.llm_provider||"gemini")){
      cfg.llm_endpoint_url=null;
    }
  }
  var agentic=gs.agentic_defaults&&typeof gs.agentic_defaults==="object"?gs.agentic_defaults:{};
  if(agentic.planner_provider!=null&&agentic.planner_provider!=="") cfg.agentic_planner_provider=agentic.planner_provider;
  if(agentic.planner_model!=null&&agentic.planner_model!=="") cfg.agentic_planner_model=agentic.planner_model;
  if(!cfg.agentic_planner_provider) cfg.agentic_planner_provider=cfg.llm_provider||"";
  if(!cfg.agentic_planner_model) cfg.agentic_planner_model=cfg.llm_model||"";
}
async function loadGlobalUiPrefs(){
  try{
    var gs=await GET("/api/settings/global");
    applyUiPrefsFromGlobal(gs);
  }catch(_){}
}
async function loadSettings(){
  try{
    var sid=S.sid||"";
    // Session listing (session-sources + sessions/available) can be slow when many
    // runs have accumulated on disk, so it's loaded lazily by the "Load Session" tab
    // instead of blocking the rest of the settings page — see loadSessionLoadTab().
    var r=await Promise.all([
      GET("/api/settings"),GET("/api/configs/regex"),GET("/api/configs/quality"),
      GET("/api/pii/ner/labels"+(sid?"?session_id="+encodeURIComponent(sid):"")).catch(function(){return {labels:DEFAULT_NER_LABELS.slice(),source:"default"};}),
      GET("/api/regex-catalog?active_only=false").catch(function(){return {patterns:[]};}),
      GET("/api/llm-providers").catch(function(){return {providers:[]};}),
    ]);
    var nerLbl=r[3]||{};
    if(sid){
      try{
        var cc=await GET("/api/sessions/"+sid+"/config");
        applyCommonConfigFromSession(cc);
      }catch(_){}
    }
    set({
      view:"settings",
      appSettings:r[0]||{},
      regexConfigs:r[1]||[],
      qualityConfigs:r[2]||[],
      nerLabels:(nerLbl.labels&&nerLbl.labels.length)?nerLbl.labels:DEFAULT_NER_LABELS.slice(),
      nerLabelsSource:nerLbl.source||"default",
      rxCat:(r[4]&&r[4].patterns)||S.rxCat||[],
      llmProviders:(r[5]&&r[5].providers)||[],
    });
    ensureLlmRefinerDefaults();
    if(r[0]&&r[0].timeouts) applyUiPrefsFromGlobal({ui_prefs:r[0].timeouts});
    else if(r[0]&&r[0].global_settings) applyUiPrefsFromGlobal(r[0].global_settings);
    loadGlobalUiPrefs().catch(function(){});
    loadLlmRoutesRuntime().catch(function(){});
  }catch(e){alert("Failed to load settings")}
}
async function loadSessionLoadTab(){
  if(S.sessionLoadRunsLoading) return;
  set({sessionLoadRunsLoading:true});
  var srcName=S.sessionLoadSource||"scan";
  var rs=await Promise.all([
    GET("/api/session-sources").catch(function(){return [];}),
    GET("/api/sessions/available?source="+encodeURIComponent(srcName)).catch(function(){return {sessions:[]};}),
  ]);
  set({
    sessionSources:rs[0]||[],
    sessionLoadRuns:(rs[1]&&rs[1].sessions)||[],
    sessionLoadRunsLoading:false,
    sessionLoadTabLoaded:true,
  });
}
async function loadAvailableSessions(){
  var src=(document.getElementById("loadSource")||{}).value||S.sessionLoadSource||"scan";
  set({sessionLoadSource:src,sessionLoadRunsLoading:true});
  try{
    var d=await GET("/api/sessions/available?source="+encodeURIComponent(src));
    set({sessionLoadRuns:d.sessions||[],sessionLoadRunsLoading:false,sessionLoadTabLoaded:true});
  }catch(e){
    set({sessionLoadRunsLoading:false});
    alert("Failed to list sessions: "+e.message);
  }
}
async function loadSessionFromDisk(){
  var runEl=document.getElementById("loadRunId");
  var srcEl=document.getElementById("loadSource");
  var runId=(runEl&&runEl.value?runEl.value.trim():"")||S.sessionLoadRunId;
  var source=(srcEl&&srcEl.value)||S.sessionLoadSource||"scan";
  if(!runId){alert("Enter or select a run id");return;}
  try{
    var resp=await POST("/api/sessions/load",{run_id:runId,source:source});
    var fin=await GET("/api/sessions/"+resp.session_id);
    applySessionPayload(fin);
    S.sessionSource=resp.source;
    S.sessionLoadRunId=runId;
    S.sessionLoadSource=source;
    await reloadLoadedSession();
    set({view:"ready"});
    toast("Loaded "+source+" run "+runId);
  }catch(e){
    var detail=e.message;
    try{var j=JSON.parse(detail);if(j.detail)detail=typeof j.detail==="string"?j.detail:JSON.stringify(j.detail);}catch(_){}
    alert("Load failed: "+detail);
  }
}
async function reloadLoadedSession(){
  if(!S.sid){alert("No session loaded");return;}
  try{
    var fin=await refreshSessionResult();
    if(fin) applySessionPayload(fin);
    try{
      var smp=await GET("/api/sessions/"+S.sid+"/sample");
      S.sample=smp;
      if(smp&&smp.total_rows!=null) S.rows=smp.total_rows;
    }catch(_){}
    try{
      var d=await GET("/api/sessions/"+S.sid+"/data/columns");
      S.columns=(d.columns||[]).map(function(c){
        var n=c.name||c.column||c;
        return{name:n,on:c.include_in_scan!==false};
      });
      S.cols=S.columns.length;
    }catch(_){}
    try{await loadApproved();}catch(_){}
    toast("Session refreshed");
    render();
  }catch(e){alert("Reload failed: "+e.message)}
}
async function loadNerModels(opts){
  opts=opts||{};
  if(S.nerModelsLoading) return;
  S.nerModelsLoading=true;
  S.nerModelsError="";
  if(opts.render!==false) render();
  try{
    var sid=S.sid||"";
    var url="/api/models"+(sid?"?session_id="+encodeURIComponent(sid):"");
    var ner=await GET(url);
    S.nerModels=ner.models||[];
    S.nerModelsDir=ner.models_dir||"";
    S.nerModelsLoaded=true;
  }catch(e){
    S.nerModelsError=e.message||String(e);
    if(!S.nerModels.length) S.nerModelsLoaded=true;
  }finally{
    S.nerModelsLoading=false;
    if(opts.render!==false) render();
  }
}
function openNerSettingsTab(){
  S.settingsTab="ner";
  if(!S.nerModelsLoaded && !S.nerModelsLoading){
    loadNerModels().catch(function(e){S.nerModelsError=e.message||String(e);render()});
  }else{
    render();
  }
}
async function uploadNerModel(inp){
  if(!inp.files||!inp.files[0])return;
  var file=inp.files[0];
  var nameEl=document.getElementById("nerUploadName");
  var name=nameEl?nameEl.value.trim():"";
  S.nerUploadBusy=true;render();
  try{
    var fd=new FormData();
    fd.append("file",file);
    if(name) fd.append("name",name);
    if(S.sid) fd.append("session_id",S.sid);
    var r=await POST("/api/models/upload",fd);
    var msg="Uploaded "+r.name;
    if(r.warnings&&r.warnings.length) msg+=" (warnings: "+r.warnings.join("; ")+")";
    alert(msg);
    if(nameEl) nameEl.value="";
    await loadNerModels();
  }catch(e){
    var detail=e.message;
    try{var j=JSON.parse(detail);if(j.detail)detail=typeof j.detail==="string"?j.detail:JSON.stringify(j.detail);}catch(_){}
    alert("Upload failed: "+detail);
  }finally{
    S.nerUploadBusy=false;
    inp.value="";
    render();
  }
}
async function activateNerModel(name){
  if(!S.sid){alert("Start or restore a scan session first — activation applies to the current session only.");return}
  try{
    var r=await POST("/api/sessions/"+S.sid+"/models/activate",{name:name});
    if(r.config){
      applyCommonConfigFromSession(r.config);
    }else{
      cfg.pii_gliner_model=r.active_path||cfg.pii_gliner_model;
      cfg.active_ner_model_name=name;
    }
    await loadNerModels();
    toast("NER model activated for this session");
    render();
  }catch(e){alert("Activate failed: "+e.message)}
}
async function deleteNerModel(name){
  if(!confirm("Delete model "+name+"? This removes weights from disk and cannot be undone.")) return;
  try{
    await DEL("/api/models/"+encodeURIComponent(name));
    if(cfg.active_ner_model_name===name){
      cfg.active_ner_model_name="";
      cfg.pii_gliner_model="";
    }
    await loadNerModels();
    toast("Model deleted");
    render();
  }catch(e){alert("Delete failed: "+e.message)}
}
async function saveGlobalSettings(){
  try{
    await PUT("/api/settings/global",{settings:{
      ui_prefs:{
        scan_mode:cfg.scan_mode,
        pii_engines:cfg.pii_engines,
        scan_wait_timeout_sec:cfg.scan_wait_timeout_sec,
        sse_ping_timeout_sec:cfg.sse_ping_timeout_sec,
      },
      automerge:cfg.automerge,
      pii:{sample_size:cfg.pii_sample_size},
    }});
    alert("Preferences saved");
  }catch(e){alert("Save failed: "+e.message)}
}
function exportConfigsBundle(){
  GET("/api/configs/export?include_catalog=true").then(function(b){
    var blob=new Blob([JSON.stringify(b,null,2)],{type:"application/json"});
    var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="redibis-configs.json";a.click();
  }).catch(function(e){alert("Export failed: "+e.message)});
}
async function importConfigsBundle(inp){
  if(!inp.files[0])return;
  try{
    var txt=await inp.files[0].text();var bundle=JSON.parse(txt);bundle.overwrite=true;
    var r=await POST("/api/configs/import",bundle);
    alert("Imported "+(r.regex||[]).length+" regex + "+(r.quality||[]).length+" quality configs");
    loadSavedConfigs();
  }catch(e){alert("Import failed: "+e.message)}
  inp.value="";
}

// ── Render ──
function render(){
  try{renderInner()}catch(e){
    console.error("render failed:",e);
    var app=document.getElementById("app");
    if(app)app.innerHTML="<main class=\"page\"><div class=\"cbox\" style=\"border-color:var(--red)\"><div class=\"stitle\">UI error</div><pre style=\"white-space:pre-wrap;font-size:.8rem\">"+E(e.message||e)+"</pre><button class=\"btn btn-red btn-sm\" onclick=\"goNewUpload()\">reset & reload upload</button></div></main>";
  }
}
function renderInner(){
  // Nav tabs
  var has=sessionActive();
  var ts=[{id:"scan",l:"scan",vs:["homepage","ready","scanning","quality-config","quality-review"]},{id:"data",l:"data",vs:["data"]},{id:"results",l:"results",vs:["results","pii","quality","pii-discover","pii-playground","quality-discover","subcontracts","subcontract-edit"]},{id:"approved",l:"approved",vs:["approved","approved-edit"]},{id:"contracts",l:"contracts",vs:["contracts","contract-detail","contract-pii","contract-quality","contract-definitions"]}];
  var apprN=(S.approved.summary&&S.approved.summary.approved)||0;
  var navTabs=document.getElementById("navTabs");
  if(navTabs){
    if(window.REDIBIS_SETTINGS_PAGE){
      navTabs.innerHTML="";
    }else{
      navTabs.innerHTML=ts.map(function(t){
        var a=t.vs.indexOf(S.view)>=0;
        var d=t.id!=="scan"&&t.id!=="contracts"&&!has;
        var badge=t.id==="approved"&&apprN>0?" <span class='chip chip-red' style='font-size:.6rem;padding:1px 5px'>"+apprN+"</span>":"";
        return "<button class=\"nav-tab"+(a?" on":"")+(d?" dis":"")+"\" data-nav=\""+t.id+"\">"+t.l+badge+"</button>";
      }).join("");
    }
  }

  // Main content
  var app=document.getElementById("app");
  if(S.view==="homepage")app.innerHTML=vHome();
  else if(S.view==="ready" || S.view==="scanning")app.innerHTML=vReady();
  else if(S.view==="results")app.innerHTML=vResults();
  else if(S.view==="pii"){
    app.innerHTML=vPII();
    if(S.sid&&(!S.columns||!S.columns.length)) ensurePiiColumns().then(function(){if(S.view==="pii")render()});
  }
  else if(S.view==="pii-discover"){
    app.innerHTML=vPIIDiscover();
    if(S.sid&&!S._piiDiscReady){
      S._piiDiscReady=true;
      Promise.all([ensurePiiColumns(),loadRx(),loadSessionRegexSet(),loadSavedConfigs(),refreshDiscovery()])
        .then(function(){if(S.view==="pii-discover")render()})
        .catch(function(){S._piiDiscReady=false});
    }
  }
  else if(S.view==="pii-playground"){
    app.innerHTML=vPIIPlayground();
    if(!S._piiPlayReady){
      S._piiPlayReady=true;
      loadPiiPlaygroundMeta().then(function(){if(S.view==="pii-playground")render();}).catch(function(){S._piiPlayReady=false;});
    }
  }
  else if(S.view==="quality")app.innerHTML=vQuality();
  else if(S.view==="quality-config")app.innerHTML=vQualityConfig();
  else if(S.view==="quality-review")app.innerHTML=vQualityReview();
  else if(S.view==="quality-discover")app.innerHTML=vQualityDiscover();
  else if(S.view==="data")app.innerHTML=vData();
  else if(S.view==="contracts")app.innerHTML=vContracts();
  else if(S.view==="contract-detail")app.innerHTML=vCD();
  else if(S.view==="contract-pii")app.innerHTML=vContractPii();
  else if(S.view==="contract-quality")app.innerHTML=vContractQuality();
  else if(S.view==="contract-definitions")app.innerHTML=vContractDefinitions();
  else if(S.view==="subcontracts")app.innerHTML=vSubContracts();
  else if(S.view==="subcontract-edit")app.innerHTML=vSubContractEdit();
  else if(S.view==="approved")app.innerHTML=vApproved();
  else if(S.view==="approved-edit")app.innerHTML=vApprovedEdit();
  else if(S.view==="settings")app.innerHTML=vSettings();
  else app.innerHTML=vHome();

  // Overlays
  var ov="";
  if(S.aboutOpen)ov+=vAbout();
  document.getElementById("overlays").innerHTML=ov;

  bind();
}

// ── Views ──
function uploadDropzoneHtml(){
  return "<div class=\"dropzone\" id=\"dz\">"+
    "<input type=\"file\" id=\"fi\" accept=\".csv,.parquet,.xlsx\" style=\"display:none\"/>"+
    "<div class=\"dz-icon\">↑</div>"+
    "<div class=\"dz-label\">drop your CSV here</div>"+
    "<div class=\"dz-hint\">or click to browse · csv / parquet / xlsx</div>"+
  "</div>";
}

function vHome(){
  var restoredBanner="";
  if(S.sid&&S.restoredSession){
    restoredBanner=
      "<div class=\"cbox\" style=\"width:760px;max-width:100%;margin-bottom:20px;border:2px solid var(--amber,#f59e0b)\">"+
        "<div class=\"stitle mb10\">previous session available</div>"+
        "<div style=\"font-size:.85rem;color:var(--muted);margin-bottom:12px\">"+
          E(S.table||S.fname||"session")+" — upload a new file below, or continue where you left off."+
        "</div>"+
        "<div class=\"row\" style=\"gap:8px;justify-content:center\">"+
          "<button class=\"btn btn-red btn-sm\" onclick=\"continueRestoredSession()\">continue session →</button>"+
          "<button class=\"btn btn-ghost btn-sm\" onclick=\"goNewUpload()\">reset & new upload</button>"+
        "</div>"+
      "</div>";
  }
  var showUploadHome=!restoredBanner;
  return "<main class=\"page\"><div class=\"home-wrap\">"+
    restoredBanner+
    (showUploadHome?
      "<div class=\"home-title\">start by uploading a CSV</div>"+
      "<div class=\"home-sub\">drop a file to profile its quality, detect PII, and draft an ODCS contract</div>"+
      uploadDropzoneHtml()
      :"")+
    (S.scanDone?"<div class=\"stitle\" style=\"margin-top:24px\">scan results</div>"+
      "<div class=\"row\" style=\"gap:8px;flex-wrap:wrap\">"+
        (S.scanLinks.quality_report?"<a href=\""+E(S.scanLinks.quality_report)+"\" target=\"_blank\" class=\"btn btn-ghost btn-sm\">quality report</a>":"")+
        (S.scanLinks.pii_contract?"<a href=\""+E(S.scanLinks.pii_contract)+"\" target=\"_blank\" class=\"btn btn-ghost btn-sm\">PII contract</a>":"")+
        (S.scanLinks.quality_contract?"<a href=\""+E(S.scanLinks.quality_contract)+"\" target=\"_blank\" class=\"btn btn-ghost btn-sm\">quality contract</a>":"")+
        (S.scanLinks.interactive_review?"<a href=\""+E(S.scanLinks.interactive_review)+"\" target=\"_blank\" class=\"btn btn-ghost btn-sm\">interactive review</a>":"")+
        "<button class=\"btn btn-ghost btn-sm\" onclick=\"set({view:'results'})\">all results →</button>"+
      "</div>":"")+"\n"+
  "</div></main>";
}

function vReady(){
  // Build artifact/result links — shown whenever we have results, regardless of view state
  var links = "";
  if(S.result) {
    if(S.result.artifacts && S.result.artifacts.run_report) {
      links += "<div>📋 <a href='/api/sessions/"+S.sid+"/artifacts/run_report' target='_blank' style='color:var(--red);text-decoration:underline;font-weight:bold'>Run Summary Report</a></div>";
    }
    if(S.result.artifacts && S.result.artifacts.interactive_review) {
      links += "<div style='margin-top:8px'>🔗 <a href='/api/sessions/"+S.sid+"/artifacts/interactive_review' target='_blank' style='color:var(--red);text-decoration:underline;font-weight:bold'>Interactive Quality Report</a></div>";
    }
    if(S.result.artifacts && S.result.artifacts.quality_contract) {
      links += "<div style='margin-top:8px'>🔗 <a href='/api/sessions/"+S.sid+"/artifacts/quality_contract' target='_blank' style='color:var(--red);text-decoration:underline;font-weight:bold'>Quality Contract (YAML)</a></div>";
    }
    if(S.result.artifacts && S.result.artifacts.quality_report) {
      links += "<div style='margin-top:8px'>🔗 <a href='/api/sessions/"+S.sid+"/artifacts/quality_report' target='_blank' style='color:var(--red);text-decoration:underline;font-weight:bold'>Quality Report</a></div>";
    }
    if(S.result.artifacts && S.result.artifacts.pii_detection_report) {
      links += "<div style='margin-top:8px'>🔗 <a href='/api/sessions/"+S.sid+"/artifacts/pii_detection_report' target='_blank' style='color:var(--red);text-decoration:underline;font-weight:bold'>PII Detection Report</a></div>";
    }
    if(S.result.artifacts && S.result.artifacts.pii_regex_review) {
      links += "<div style='margin-top:8px'>🔗 <a href='#' data-act='open-pii-discover' style='color:var(--red);text-decoration:underline;font-weight:bold'>PII Discovery (engines, regex, columns)</a></div>";
    }
    links += "<div style='margin-top:8px'>🔗 <a href='#' data-act='open-pii-playground' style='color:var(--red);text-decoration:underline;font-weight:bold'>PII Text Playground (free-text spans)</a></div>";
    if(S.result.quality_contract_version) {
      links += "<div style='margin-top:8px'>🔗 <a href='#' onclick='set({view:\"contracts\"});setTimeout(()=>loadCD(\""+S.result.table_name+"\"),100)' style='color:var(--red);text-decoration:underline;font-weight:bold'>View Quality Contract (v"+S.result.quality_contract_version+")</a></div>";
    }
    if(S.result.pii_contract_version) {
      links += "<div style='margin-top:8px'>🔗 <a href='#' onclick='set({view:\"contracts\"});setTimeout(()=>loadCD(\""+S.result.table_name+"\"),100)' style='color:var(--red);text-decoration:underline;font-weight:bold'>View PII Contract (v"+S.result.pii_contract_version+")</a></div>";
    }
  }
  var linkBox = links ? "<div class='cbox' style='width:100%;margin-bottom:24px;border:2px solid var(--red)'><div class='stitle mb10'>Generated Artifacts & Contracts</div>"+links+"</div>" : "";

  // Scanning progress block — only shown while actively scanning
  var scanBlock = "";
  if(S.view === "scanning") {
    var prg="<div class=\"pbar\"><div class=\"pfill\" style=\"width:"+S.prog+"%\">"+S.prog+"%</div></div>";
    var logHtml="<div class=\"logbox\" id=\"logPanel\" style=\"width:100%\">"+S.logs.map(function(l){return "<div class=\""+l.c+"\">"+E(l.m)+"</div>"}).join("")+"</div>";
    scanBlock =
      "<div class=\"stitle log-toggle\" onclick=\"toggleLog()\" style=\"margin-top:8px\"><span id=\"logArrow\">▾</span> scan log ("+S.logs.length+")</div>" + logHtml +
      "<div class=\"row\" style=\"gap:8px;margin-top:16px\">" +
        "<button class=\"btn btn-ghost\" id=\"btnCancel\" style=\"color:var(--red);border-color:var(--red)\">✗ cancel scan</button>" +
        (S.result ? "<button class=\"btn btn-ghost\" style=\"color:var(--ink);border-color:var(--ink)\" onclick=\"resetSession()\">← reset & new upload</button>" : "") +
      "</div>";
    scanBlock = prg + scanBlock;
  } else if(S.result && !S.restoredSession) {
    // Done — show reset option below the artifacts
    scanBlock = "<div style='margin-top:16px;text-align:center'><button class=\"btn btn-ghost\" onclick=\"resetSession()\">← reset & new upload</button></div>";
  }

  var uploadBlock="";
  if(!S.file && !S.restoredSession){
    uploadBlock=
      "<div class=\"cbox\" style=\"width:100%;margin-bottom:20px;border:2px dashed var(--border)\">"+
        "<div class=\"stitle mb10\">upload a new CSV</div>"+
        "<div style=\"font-size:.78rem;color:var(--muted);margin-bottom:12px\">"+
          (S.sid?"Restored session — upload a file to replace it, or ":"")+
          "<button class=\"btn btn-ghost btn-sm\" onclick=\"goNewUpload()\">reset & start over</button>"+
        "</div>"+
        uploadDropzoneHtml()+
      "</div>";
  } else if(!S.file && S.restoredSession){
    uploadBlock=
      "<div class=\"cbox\" style=\"width:100%;margin-bottom:20px;border:2px solid var(--amber,#f59e0b)\">"+
        "<div class=\"stitle mb10\">restored session loaded</div>"+
        "<div style=\"font-size:.78rem;color:var(--muted);margin-bottom:12px\">This session is already loaded. Reset to start over with a new file.</div>"+
        "<button class=\"btn btn-ghost btn-sm\" onclick=\"goNewUpload()\">reset & start over</button>"+
      "</div>";
  }

  return "<main class=\"page\"><div class=\"widget-wrap\">"+
    (S.file?"<div class=\"file-info\">"+E(S.fname)+" <span>· "+S.cols+" cols · "+((S.rows||0).toLocaleString())+" rows</span></div>":"")+
    uploadBlock+
    "<div class=\"chips\">"+
      "<div class=\"wchip\" data-chip=\"pii\"><div class=\"cn\">PII</div><div class=\"cs\">privacy</div></div>"+
      "<div class=\"wchip\" data-chip=\"data\"><div class=\"cn\">DATA</div><div class=\"cs\">schema</div></div>"+
      "<div class=\"wchip\" data-chip=\"quality\"><div class=\"cn\">QUALITY</div><div class=\"cs\">rules</div></div>"+
    "</div>"+
    // Unified scan button — reads cfg.scan_mode
    "<div style='margin-bottom:20px;display:flex;flex-direction:column;align-items:center;gap:10px'>"+
      "<button class='btn btn-red' style='width:300px;height:56px;font-size:18px;font-weight:800;letter-spacing:-.01em' onclick='doScan()'>"+
        "scan"+
      "</button>"+
      "<div class='row' style='gap:8px'>"+
        "<button class='btn btn-ghost btn-sm' onclick='doScan(\"pii\")'>PII only</button>"+
        "<button class='btn btn-ghost btn-sm' onclick='doScan(\"quality\")'>Quality only</button>"+
        "<button class='btn btn-ghost btn-sm' onclick='doScan(\"both\")'>Both</button>"+
        "<a class='btn btn-ghost btn-sm' href='/settings'>⚙ settings</a>"+
      "</div>"+
      "<div style='font-size:.72rem;color:var(--muted);font-family:\"IBM Plex Mono\",monospace'>"+
        "engines: "+cfg.pii_engines+" · regex ≥ "+cfg.pii_regex_confidence+" · gliner ≥ "+cfg.pii_gliner_confidence+
        (cfg.pii_regex_config_name?" · regex: "+cfg.pii_regex_config_name:"")+
        (cfg.quality_config_name?" · quality: "+cfg.quality_config_name:"")+
      "</div>"+
    "</div>"+
    linkBox+
    scanBlock+
  "</div></main>";
}


