      "<div><strong>Export complete</strong> · run <span class=\"mono\">"+E(exp.run_id)+"</span> · "+
      exp.rows+" rows · keys kept back (not exported)</div>"+
      "<div class=\"row\" style=\"gap:8px\">"+
        "<a class=\"btn btn-ghost btn-sm\" href=\"/api/sessions/"+S.sid+"/mask/audit/download\" target=\"_blank\">↓ audit report</a>"+
        "<a class=\"btn btn-ghost btn-sm\" href=\"/api/sessions/"+S.sid+"/mask/manifest\" target=\"_blank\">manifest</a>"+
      "</div></div>";
