function discRunHistory(kind){
  var runs=(S.discRuns||[]).filter(function(r){return r.kind===kind});
  if(!runs.length)return "";
  return "<div class='stitle' style='margin-top:20px'>past "+kind+" discovery runs ("+runs.length+")</div>"+
    "<div class='card' style='padding:0;overflow:auto;max-height:200px'><table class='tbl' style='font-size:.74rem'><tbody>"+
    runs.slice().reverse().map(function(r){
      var sc=r.status==="complete"?"chip-green":r.status==="error"?"chip-red":"chip-amber";
      return "<tr style='cursor:pointer' onclick=\"loadDiscoveryRun('"+r.run_id+"')\">"+
        "<td class='mono' style='font-size:.68rem'>"+E(r.run_id)+"</td>"+
        "<td><span class='chip "+sc+"'>"+r.status+"</span></td>"+
        "<td class='mono'>"+E((r.columns||["all"]).join(","))+"</td>"+
        "<td class='mono'>"+E(JSON.stringify(r.summary||{}))+"</td></tr>";
    }).join("")+"</tbody></table></div>";
}
