function vSettingsAgentsTab(){
  var rt=S.agentsRuntime||null;
  if(S._agentsRuntimeLoading){
    return "<div class='cbox'><div class='stitle mb10'>Agents / runtime</div>"+
      "<div style='color:var(--muted)'>Loading runtime configuration…</div></div>";
  }
  if(!rt){
    return "<div class='cbox'><div class='stitle mb10'>Agents / runtime</div>"+
      "<div style='color:var(--muted);margin-bottom:12px'>Runtime status not loaded yet.</div>"+
      "<button class='btn btn-sm btn-ghost' onclick='loadAgentsRuntimeTab()'>Load</button></div>";
  }
  var sections=rt.sections||{};
  var sourceChip=rt.config_source==="REDIBIS_CONFIG"
    ?"Deployment config active"
    :"Built-in / global settings";
  var cards=Object.keys(sections).map(function(name){
    var values=sections[name]||{};
    var restart=!!values.restart_required;
    var rows=Object.keys(values).filter(function(k){
      return k!=="editable"&&k!=="restart_required";
    }).map(function(k){
      var v=values[k];
      var shown=(typeof v==="boolean")?(v?"on":"off"):(v==null||v===""?"not set":String(v));
      return "<div class='runtime-row'><span class='runtime-key'>"+E(k.replace(/_/g," "))+"</span>"+
        "<span class='runtime-value'>"+E(shown)+"</span></div>";
    }).join("");
    return "<article class='runtime-card'>"+
      "<div style='display:flex;justify-content:space-between;gap:12px;margin-bottom:8px'>"+
        "<h3 style='margin:0;text-transform:capitalize;font-size:.9rem'>"+E(name)+"</h3>"+
        "<span class='chip'>"+(restart?"Restart required":"Hot setting")+"</span>"+
      "</div>"+rows+
    "</article>";
  }).join("");
  return "<div class='cbox'>"+
    "<div class='stitle mb10'>Agents / runtime</div>"+
    "<div style='font-size:.82rem;color:var(--muted);margin-bottom:12px'>"+
      "Deployment-controlled agent flags (enabled, executors, RAI, memory, behavior) are visible here. "+
      "Edit YAML (<span class='mono'>REDIBIS_CONFIG</span>) and restart for locked fields. "+
      "Planner / enrichment defaults remain editable under the <strong>LLM</strong> tab."+
    "</div>"+
    "<div class='row' style='gap:8px;margin-bottom:14px;align-items:center;flex-wrap:wrap'>"+
      "<span class='chip'>"+E(sourceChip)+"</span>"+
      "<button class='btn btn-sm btn-ghost' onclick='loadAgentsRuntimeTab()'>↺ refresh</button>"+
    "</div>"+
    "<div class='runtime-grid'>"+(cards||"<div style='color:var(--muted)'>No runtime sections.</div>")+"</div>"+
  "</div>";
}

