async function saveCustomProviderFromSettings(){
  var status=document.getElementById("providerSaveStatus");
  var name=((document.getElementById("customProviderName")||{}).value||"").trim().toLowerCase();
  var litellmModel=((document.getElementById("customProviderModel")||{}).value||"").trim();
  if(!name||!litellmModel){
    if(status) status.textContent="Registry name and LiteLLM model are required.";
    return;
  }
  if(status) status.textContent="Saving…";
  try{
    await POST("/api/llm/providers",{
      name:name,
      description:"Custom provider "+name,
      profile_type:"openai_compatible",
      litellm_model:litellmModel,
      model:litellmModel.indexOf("/")>=0?litellmModel.split("/").slice(1).join("/"):litellmModel,
      model_prefix:litellmModel.indexOf("/")>=0?litellmModel.split("/")[0]:"openai",
      api_base:((document.getElementById("customProviderBase")||{}).value||"").trim()||null,
      api_key_env:((document.getElementById("customProviderKeyEnv")||{}).value||"").trim(),
      supports_json:true,
      residency:((document.getElementById("customProviderResidency")||{}).value)||"local",
      params:{},
      known_models:[],
    });
    await loadLlmProviders();
    if(status) status.textContent="Provider saved.";
    toast("Provider saved");
  }catch(e){
    if(status) status.textContent="Save failed: "+(e.message||e);
  }
}

