function applySettingsScan(){
  var eq=document.getElementById("s_equation");
  if(eq) cfg.equation=eq.value;
  var am=document.getElementById("s_automerge");
  if(am) cfg.automerge=am.value;
  var st=document.getElementById("s_scan_timeout");
  if(st){
    var sw=parseInt(st.value,10);
    if(!isNaN(sw)) cfg.scan_wait_timeout_sec=Math.max(60,Math.min(sw,7200));
  }
  var sse=document.getElementById("s_sse_timeout");
  if(sse){
    var sv=parseFloat(sse.value);
    if(!isNaN(sv)) cfg.sse_ping_timeout_sec=Math.max(5,Math.min(sv,300));
  }
  render();
}
function readSettingsPiiFromDom(){
  var eng=document.getElementById("s_pii_engines");
  var rc=document.getElementById("s_regex_conf");
  var gc=document.getElementById("s_gliner_conf");
  var ga=document.getElementById("s_gliner_always");
  var up=document.getElementById("s_use_phonenumbers");
  var pss=document.getElementById("s_pii_sample_size");
  if(eng) cfg.pii_engines=eng.value;
  if(rc) cfg.pii_regex_confidence=parseFloat(rc.value);
  if(gc) cfg.pii_gliner_confidence=parseFloat(gc.value);
  if(ga) cfg.pii_gliner_always_run=ga.checked;
  if(up) cfg.use_phonenumbers=up.checked;
  if(pss){
    var n=parseInt(pss.value,10);
    if(!isNaN(n)&&n>=1) cfg.pii_sample_size=n;
  }
}
