function bindConfSliders(){
  function fmt(v){
    v=parseFloat(v);
    if(isNaN(v)) return "—";
    var s=v.toFixed(2);
    if(s.indexOf(".")>=0) s=s.replace(/0+$/,"").replace(/\.$/,"");
    return s;
  }
  document.querySelectorAll("input[type='range'][data-show]").forEach(function(el){
    var showId=el.getAttribute("data-show");
    var show=showId?document.getElementById(showId):null;
    function sync(){
      var v=parseFloat(el.value);
      if(show) show.textContent=fmt(v);
      if(el.id==="s_regex_conf") cfg.pii_regex_confidence=v;
      else if(el.id==="s_gliner_conf") cfg.pii_gliner_confidence=v;
    }
    el.oninput=sync;
    sync();
  });
  var eng=document.getElementById("s_pii_engines");
  if(eng) eng.onchange=function(){cfg.pii_engines=eng.value;};
  var ga=document.getElementById("s_gliner_always");
  if(ga) ga.onchange=function(){cfg.pii_gliner_always_run=ga.checked;};
}
