async function exportDefaultPack(){
  try{
    var r=await fetch("/api/rdbpack/export-default");
    if(!r.ok) throw new Error(await r.text());
    var blob=await r.blob();
    var a=document.createElement("a");
    a.href=URL.createObjectURL(blob);
    a.download="redibis-default.rdbpack";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function(){URL.revokeObjectURL(a.href);},1000);
    toast("Downloaded redibis-default.rdbpack");
  }catch(e){
    toast("Export failed: "+(e.message||e));
  }
}
async function dryRunPackImport(input){
  var file=input&&input.files&&input.files[0];
  if(!file) return;
  S.packPendingFile=file;
  try{
    var fd=new FormData();
    fd.append("file",file);
    fd.append("dry_run","true");
    var r=await fetch("/api/rdbpack/import",{method:"POST",body:fd});
    var j=await r.json().catch(function(){return {};});
    if(!r.ok) throw new Error(j.detail||r.statusText||"dry-run failed");
    S.packDryRun=j;
    render();
  }catch(e){
    S.packPendingFile=null;
    S.packDryRun=null;
    toast("Pack dry-run: "+(e.message||e));
  }
  if(input) input.value="";
}
async function confirmPackImport(){
  if(!S.packPendingFile){ toast("No pending pack file"); return; }
  var activate=!!(document.getElementById("packActivateChk")&&document.getElementById("packActivateChk").checked);
  try{
    var fd=new FormData();
    fd.append("file",S.packPendingFile);
    fd.append("dry_run","false");
    fd.append("activate",activate?"true":"false");
    var r=await fetch("/api/rdbpack/import",{method:"POST",body:fd});
    var j=await r.json().catch(function(){return {};});
    if(!r.ok) throw new Error(j.detail||r.statusText||"import failed");
    S.packLastImport=j;
    S.packDryRun=null;
    S.packPendingFile=null;
    toast("Imported "+(j.identity||"pack"));
    S.promptsLoaded=false;
    await loadPacksPanel();
    if(j.prompts && j.prompts.count) await loadPromptsPanel();
  }catch(e){
    toast("Pack import: "+(e.message||e));
  }
}
