async function loadSessionRegexSet(){
  if(!S.sid){S.regexSet={name:null,replace_all:false,patterns:{}};return}
  try{
    var doc=await GET("/api/sessions/"+S.sid+"/config");
    S.regexSet=doc.regex_set||{name:null,replace_all:false,patterns:{}};
  }catch(e){
    S.regexSet=S.regexSet||{name:null,replace_all:false,patterns:{}};
  }
}
async function syncRegexSetToSession(){
  if(!S.sid)return;
  var rs=S.regexSet||{name:null,replace_all:false,patterns:{}};
  S.regexSet=await PUT("/api/sessions/"+S.sid+"/config/regex",{
    name:rs.name||cfg.pii_regex_config_name||null,
    replace_all:!!rs.replace_all,
    patterns:rs.patterns||{}
  });
}
