async function testPiiRegex(){
  capturePiiRxDraft();
  var d=S.piiRxDraft||{};
  try{
    await ensureSession();
    if(!d.pattern||!d.pattern.trim()){alert("Enter a regex pattern");return}
    var pasted=d.testVal?d.testVal.trim().split(/\n/).map(function(s){return s.trim()}).filter(Boolean):[];
    var hasCol=!!(d.testCol&&d.testCol.trim());
    if(!pasted.length&&!hasCol){alert("Paste manual test values and/or pick a sample column.");return}
    var entry=d.listPatternKey?(S.regexSet&&S.regexSet.patterns||{})[d.listPatternKey]:null;
    var body={
      pattern:d.pattern.trim(),
      entity_type:d.entity||"CUSTOM",
      recognizer_group:d.matchMode||"structured",
      test_values:pasted
    };
    if(hasCol) body.column=d.testCol.trim();
    var norm=piiRxNormalizer(d,entry);
    if(norm) body.normalizer=norm;
    S.piiRegexTest=await POST("/api/sessions/"+S.sid+"/discovery/pii/test-regex",body);
    updatePiiRxTestResult();
  }catch(e){
    var msg=e.message||String(e);
    try{var j=JSON.parse(msg);if(j.detail) msg=j.detail;}catch(_){}
    alert("Regex test failed: "+msg);
  }
}
async function addPiiRegexToActive(){
  capturePiiRxDraft();
  var d=S.piiRxDraft||{};
  if(!d.pattern||!d.pattern.trim()){alert("Enter a pattern first");return}
  var k=(d.key&&d.key.trim())||("custom_"+Date.now());
  S.regexSet=S.regexSet||{name:null,replace_all:false,patterns:{}};
  S.regexSet.patterns=S.regexSet.patterns||{};
  S.regexSet.patterns[k]={
    pattern:d.pattern.trim(),
    entity_type:d.entity||"CUSTOM",
    recognizer_group:d.matchMode||"structured",
    presidio_score:0.85,
    requires_normalizer:(d.msisdnNorm!==false&&(d.entity||"").toUpperCase()==="PHONE_NUMBER")?"normalize_msisdn_egypt":null
  };
  try{
    await ensureSession();
    await syncRegexSetToSession();
    toast("Added pattern "+k+" to active list");
    render();
  }catch(e){alert(e.message)}
}
