async function saveDiscoveryRegexConfig(){
  var rs=S.regexSet||{patterns:{}};
  var nPat=Object.keys(rs.patterns||{}).length;
  if(!nPat&&!rs.replace_all){alert("Add at least one pattern first");return}
  var name=prompt("Name for this regex config (saved to registry):");
  if(!name)return;
  var desc=prompt("Description (optional):","")||"";
  try{
    await ensureSession();
    await POST("/api/configs/regex",{
      name:name,description:desc,
      overrides:{replace_all:!!rs.replace_all,add:rs.patterns||{}}
    });
    rs.name=name; S.regexSet=rs;
    cfg.pii_regex_config_name=name;
    await syncRegexSetToSession();
    await loadSavedConfigs();
    toast("Saved regex config '"+name+"'");
    render();
  }catch(e){alert("Save failed: "+e.message)}
}
async function applyActiveRegexToScan(){
  try{
    await ensureSession();
    await syncRegexSetToSession();
    var eng=document.getElementById("discEngines");
    var gm=document.getElementById("discGModel");
    var rc=document.getElementById("discRegexConf");
    var gc=document.getElementById("discGlinerConf");
    if(eng) cfg.pii_engines=eng.value;
    if(gm) cfg.pii_gliner_model=gm.value;
    if(rc&&rc.value) cfg.pii_regex_confidence=parseFloat(rc.value);
    if(gc&&gc.value) cfg.pii_gliner_confidence=parseFloat(gc.value);
    if(S.regexSet&&S.regexSet.name) cfg.pii_regex_config_name=S.regexSet.name;
    await PATCH("/api/sessions/"+S.sid+"/config",{fields:{
      pii_engines:cfg.pii_engines,
      pii_gliner_model:cfg.pii_gliner_model,
      pii_regex_confidence:cfg.pii_regex_confidence,
      pii_gliner_confidence:cfg.pii_gliner_confidence
    }});
    toast("Scan config updated — regex list + engines apply on next PII scan");
    render();
  }catch(e){alert(e.message)}
}
